// Every user-visible string in the system, in English, Kinyarwanda, French and
// Kiswahili -- and the three functions that read them.
//
// WHY THIS IS IN shared/ AND NOT IN src/.
//
// It is read by both sides. The browser reads it through src/i18n.js, which
// adds the React context, the hooks and the remembered choice in localStorage;
// the API reads it directly, because a report exported as a PDF or a
// spreadsheet has to be written in the language its reader chose. Before this,
// the dictionary lived in src/i18n.js next to `import ... from 'react'`, so the
// API could not touch it -- and the exports were English only, in a system
// whose whole interface is in four languages and whose reports are printed and
// carried to meetings. The alternative was a second dictionary on the server,
// which is the same two-copies-drift this file exists to prevent (see the
// comment on the entries below).
//
// This is the same reasoning that puts the four business-operation names in
// shared/businessOperations.js: a name the API needs cannot live in a module
// that imports React.
//
// One entry per key, with all four languages on the same line. The alternative
// -- four separate dictionaries -- makes it impossible to see at a glance
// whether a key has been translated everywhere, and they drift the moment
// somebody adds a string to one and not the others. Here a gap is visible on
// the line itself, and `missingTranslations()` below finds any that slip past.
//
// A missing language falls back to English, and an unknown key falls back to
// the key itself, so a gap shows readable English rather than a blank element.
//
// The four business-operation names are NOT here. They live in
// shared/businessOperations.js, with their translations, because the API needs
// the same names. Use `operationName(id, language)` for those.

export const LANGUAGES = [
  { code: 'en', name: 'English', nativeName: 'English' },
  { code: 'rw', name: 'Kinyarwanda', nativeName: 'Kinyarwanda' },
  { code: 'fr', name: 'French', nativeName: 'Français' },
  { code: 'sw', name: 'Kiswahili', nativeName: 'Kiswahili' }
];

export const LANGUAGE_CODES = LANGUAGES.map((language) => language.code);

// One of the four, for a language that arrived from outside -- a query string,
// a stored preference, a header. Anything else reads as English rather than
// being trusted into a lookup.
export function knownLanguage(value) {
  const code = String(value || '').slice(0, 2).toLowerCase();
  return LANGUAGE_CODES.includes(code) ? code : 'en';
}

