  'next.draftText': { en: 'Send it for approval when it is ready.', rw: 'Byohereze kwemezwa igihe byiteguye.', fr: 'Envoyez-le pour approbation quand il est prêt.', sw: 'Itume kwa idhini ikiwa tayari.' },
  'next.draftOther': { en: 'The person who wrote it has not sent it yet.', rw: 'Uwabyanditse ntarabyohereza.', fr: 'La personne qui l’a rédigé ne l’a pas encore envoyé.', sw: 'Aliyeiandika bado hajaituma.' },
  'next.decideTitle': { en: 'Needs your decision', rw: 'Bikeneye icyemezo cyawe', fr: 'Attend votre décision', sw: 'Inahitaji uamuzi wako' },
  'next.decideText': { en: 'Read the details below, then approve or reject it.', rw: 'Soma ibisobanuro biri hepfo, hanyuma ubyemeze cyangwa ubyange.', fr: 'Lisez les détails ci-dessous, puis approuvez ou rejetez.', sw: 'Soma maelezo hapa chini, kisha idhinisha au kataa.' },
  'next.goDecide': { en: 'Decide now', rw: 'Fata icyemezo', fr: 'Décider maintenant', sw: 'Amua sasa' },
  'next.waitingFor': { en: 'Waiting for {name}', rw: 'Bitegereje {name}', fr: 'En attente de {name}', sw: 'Inamsubiri {name}' },
  'next.waitingForText': { en: 'Nothing to do here until they decide.', rw: 'Nta kindi cyo gukora hano kugeza bafashe icyemezo.', fr: 'Rien à faire ici tant que la décision n’est pas prise.', sw: 'Hakuna la kufanya hapa hadi waamue.' },
  'next.monthClosedTitle': { en: 'This month is closed', rw: 'Uku kwezi kwarafunzwe', fr: 'Ce mois est clôturé', sw: 'Mwezi huu umefungwa' },
  'next.monthClosedText': { en: 'Nothing more can be changed. Ask the Director to reopen the month if something is wrong.', rw: 'Nta kindi gishobora guhindurwa. Saba Umuyobozi Mukuru kongera gufungura ukwezi niba hari ikitagenda.', fr: 'Plus rien ne peut être modifié. Demandez au Directeur de rouvrir le mois en cas d’erreur.', sw: 'Hakuna kinachoweza kubadilishwa tena. Mwombe Mkurugenzi afungue mwezi upya ikiwa kuna kosa.' },
  'next.pausedText': { en: 'The Director has paused this work.', rw: 'Umuyobozi Mukuru yahagaritse aka kazi by’agateganyo.', fr: 'Le Directeur a mis ce travail en pause.', sw: 'Mkurugenzi amesitisha kazi hii.' },
  'next.doneOn': { en: 'Finished on {date}.', rw: 'Byarangiye ku wa {date}.', fr: 'Terminé le {date}.', sw: 'Ilikamilika tarehe {date}.' },
  'next.finalCheckTitle': { en: 'Ready for your final check', rw: 'Biteguye isuzuma ryawe rya nyuma', fr: 'Prêt pour votre vérification finale', sw: 'Tayari kwa ukaguzi wako wa mwisho' },
  'next.finalCheckText': { en: 'Look at the proof, then mark it done or send it back with what to fix.', rw: 'Reba ibimenyetso, hanyuma ubyemeze ko byarangiye cyangwa ubigarure uvuge ibyo gukosora.', fr: 'Consultez les justificatifs, puis marquez-le terminé ou renvoyez-le en indiquant quoi corriger.', sw: 'Angalia ushahidi, kisha weka imekamilika au irudishe ukieleza cha kurekebisha.' },
  'next.withDirectorTitle': { en: 'With the Director', rw: 'Biri ku Muyobozi Mukuru', fr: 'Chez le Directeur', sw: 'Iko kwa Mkurugenzi' },
  'next.monthNotConfirmedTitle': { en: 'Waiting for the month to be confirmed', rw: 'Bitegereje ko ukwezi kwemezwa', fr: 'En attente de la confirmation du mois', sw: 'Inasubiri mwezi uthibitishwe' },
  'next.readyTitle': { en: 'Ready to start', rw: 'Biteguye gutangira', fr: 'Prêt à commencer', sw: 'Tayari kuanza' },
  'next.readyText': { en: 'It is approved. Start it when the work begins.', rw: 'Byemejwe. Tangira akazi igihe ubitangiye.', fr: 'C’est approuvé. Démarrez le travail quand vous commencez.', sw: 'Imeidhinishwa. Anza kazi unapoanza.' },
  'next.readyOther': { en: 'Approved — waiting for {name} to start', rw: 'Byemejwe — bitegereje ko {name} atangira', fr: 'Approuvé — en attente du démarrage par {name}', sw: 'Imeidhinishwa — inamsubiri {name} aanze' },
  'next.underwayTitle': { en: 'Work under way', rw: 'Akazi karakorwa', fr: 'Travail en cours', sw: 'Kazi inaendelea' },
  'next.underwayText': { en: 'Record what you spend and add receipts and photos as you go. When the work is finished, send it for a final check.', rw: 'Andika ibyo ukoresha kandi wongeremo inyemezabwishyu n’amafoto uko ukomeza. Akazi nikarangira, kohereze gusuzumwa bwa nyuma.', fr: 'Enregistrez vos dépenses et ajoutez reçus et photos au fur et à mesure. Une fois le travail fini, envoyez-le pour vérification finale.', sw: 'Rekodi unachotumia na ongeza risiti na picha unapoendelea. Kazi ikikamilika, itume kwa ukaguzi wa mwisho.' },
  'next.underwayOther': { en: 'Under way with {name}', rw: 'Birakorwa na {name}', fr: 'En cours avec {name}', sw: 'Inaendelea na {name}' },
  'next.addProof': { en: 'Add photos or receipts', rw: 'Ongeramo amafoto cyangwa inyemezabwishyu', fr: 'Ajouter photos ou reçus', sw: 'Ongeza picha au risiti' },
  'next.tripApprovedTitle': { en: 'Trip approved', rw: 'Urugendo rwemejwe', fr: 'Déplacement approuvé', sw: 'Safari imeidhinishwa' },
  'next.tripApprovedText': { en: 'Record the money when you hand it over, or mark the trip under way.', rw: 'Andika amafaranga igihe uyatanze, cyangwa ugaragaze ko urugendo rwatangiye.', fr: 'Enregistrez l’argent quand vous le remettez, ou marquez le déplacement en cours.', sw: 'Rekodi pesa unapozikabidhi, au weka safari inaendelea.' },
  'next.tripWithDirector': { en: 'The Director hands over the money and starts the trip.', rw: 'Umuyobozi Mukuru ni we utanga amafaranga agatangiza urugendo.', fr: 'Le Directeur remet l’argent et lance le déplacement.', sw: 'Mkurugenzi hukabidhi pesa na kuanzisha safari.' },
  'next.tripFundedText': { en: 'Mark the trip under way when it starts.', rw: 'Garagaza ko urugendo rwatangiye igihe rutangiye.', fr: 'Marquez le déplacement en cours quand il commence.', sw: 'Weka safari inaendelea inapoanza.' },
  'next.tripAddReceipts': { en: 'Add receipts and photos as the trip goes on.', rw: 'Ongeramo inyemezabwishyu n’amafoto uko urugendo rukomeza.', fr: 'Ajoutez reçus et photos au fil du déplacement.', sw: 'Ongeza risiti na picha safari inavyoendelea.' },
  'next.tripUnderwayText': { en: 'Record what was actually spent, then mark the trip done.', rw: 'Andika ibyakoreshejwe koko, hanyuma ugaragaze ko urugendo rwarangiye.', fr: 'Enregistrez ce qui a réellement été dépensé, puis marquez le déplacement terminé.', sw: 'Rekodi kilichotumika hasa, kisha weka safari imekamilika.' },
