  'email.invite.button': { en: 'Choose my password', rw: 'Hitamo ijambobanga ryanjye', fr: 'Choisir mon mot de passe', sw: 'Chagua nenosiri langu' },
  'email.invite.body': { en: 'Hello {name},\n\n{director} has given you access to the Project Operations Management System (PMS), where you can follow the projects shared with you.\n\nOpen this link to choose your password:\n{link}\n\nYour username is {username}. The link works once, for {days} days.', rw: 'Muraho {name},\n\n{director} yaguhaye uburenganzira bwo kwinjira muri Project Operations Management System (PMS), aho ushobora gukurikirana imishinga musangiye.\n\nFungura iri huza uhitemo ijambobanga ryawe:\n{link}\n\nIzina ryawe ni {username}. Ihuza rikora rimwe, mu minsi {days}.', fr: 'Bonjour {name},\n\n{director} vous a donné accès au Project Operations Management System (PMS), où vous pouvez suivre les projets partagés avec vous.\n\nOuvrez ce lien pour choisir votre mot de passe :\n{link}\n\nVotre identifiant est {username}. Le lien ne sert qu’une fois, pendant {days} jours.', sw: 'Habari {name},\n\n{director} amekupa ruhusa ya kuingia kwenye Project Operations Management System (PMS), ambapo unaweza kufuatilia miradi uliyoshirikishwa.\n\nFungua kiungo hiki kuchagua nenosiri lako:\n{link}\n\nJina lako la mtumiaji ni {username}. Kiungo kinatumika mara moja, kwa siku {days}.' },
  'email.invite.subject': { en: '{director} invited you to PMS', rw: '{director} yagutumiye muri PMS', fr: '{director} vous invite sur PMS', sw: '{director} amekualika kwenye PMS' },
  'invite.gone': { en: 'This invitation link has expired or was already used. Ask the Director for a new one.', rw: 'Iri huza ry’ubutumire ryarangiye cyangwa ryarakoreshejwe. Saba Umuyobozi irindi.', fr: 'Ce lien d’invitation a expiré ou a déjà servi. Demandez-en un nouveau au Directeur.', sw: 'Kiungo hiki cha mwaliko kimeisha muda au kimeshatumika. Muombe Mkurugenzi kingine.' },
  'invite.goneTitle': { en: 'This link no longer works', rw: 'Iri huza ntirigikora', fr: 'Ce lien ne fonctionne plus', sw: 'Kiungo hiki hakifanyi kazi tena' },
  'invite.welcome': { en: 'Your password is set. Welcome to PMS.', rw: 'Ijambobanga ryawe ryashyizweho. Murakaza neza muri PMS.', fr: 'Votre mot de passe est enregistré. Bienvenue dans PMS.', sw: 'Nenosiri lako limewekwa. Karibu PMS.' },
  'invite.start': { en: 'Save and open PMS', rw: 'Bika ufungure PMS', fr: 'Enregistrer et ouvrir PMS', sw: 'Hifadhi na ufungue PMS' },
  'invite.blurb': { en: 'Your username is {username}. Choose the password you will sign in with.', rw: 'Izina ryawe ni {username}. Hitamo ijambobanga uzajya winjiriraho.', fr: 'Votre identifiant est {username}. Choisissez le mot de passe avec lequel vous vous connecterez.', sw: 'Jina lako la mtumiaji ni {username}. Chagua nenosiri utakalotumia kuingia.' },
  'invite.title': { en: 'Welcome, {name}', rw: 'Murakaza neza, {name}', fr: 'Bienvenue, {name}', sw: 'Karibu, {name}' },
  'msg.inviteLink': { en: 'The email could not be sent. Send {name} ({email}) this link, by WhatsApp or email:\n\n{link}\n\nIt works once, for 7 days.', rw: 'Email ntiyashoboye koherezwa. Oherereza {name} ({email}) iri huza, kuri WhatsApp cyangwa email:\n\n{link}\n\nRikora rimwe, mu minsi 7.', fr: 'L’email n’a pas pu être envoyé. Envoyez ce lien à {name} ({email}), par WhatsApp ou email :\n\n{link}\n\nIl ne sert qu’une fois, pendant 7 jours.', sw: 'Barua pepe haikuweza kutumwa. Mtumie {name} ({email}) kiungo hiki, kwa WhatsApp au barua pepe:\n\n{link}\n\nKinatumika mara moja, kwa siku 7.' },
