  'msg.inviteEmailed': { en: 'An invitation was emailed to {name} at {email}. The link works for 7 days.', rw: 'Ubutumire bwoherejwe kuri {name} kuri {email}. Ihuza rikora iminsi 7.', fr: 'Une invitation a été envoyée à {name} à {email}. Le lien est valable 7 jours.', sw: 'Mwaliko umetumwa kwa {name} kwenye {email}. Kiungo kinafanya kazi kwa siku 7.' },
