  'report.blurb': { en: 'See what was done, what it cost and what is left, for any dates you choose.', rw: 'Reba ibyakozwe, ibyo byatwaye n’ibisigaye, ku matariki uhitamo.', fr: 'Voyez ce qui a été fait, ce que cela a coûté et ce qui reste, pour les dates de votre choix.', sw: 'Ona kilichofanyika, kilichogharimu na kilichobaki, kwa tarehe unazochagua.' },
  'report.working': { en: 'Working…', rw: 'Birimo gukorwa...', fr: 'Traitement en cours...', sw: 'Inafanya kazi...' },
  'report.chooseValidRange': { en: 'Choose a start date on or before the end date.', rw: 'Hitamo itariki itangira iri mbere cyangwa ingana n’iyo irangira.', fr: 'Choisissez une date de début antérieure ou égale à la date de fin.', sw: 'Chagua tarehe ya kuanza iliyo kabla au sawa na tarehe ya mwisho.' },
  'report.noneInPeriod': { en: 'No work in those dates. Try a wider range of dates.', rw: 'Nta kazi muri izo tariki. Gerageza itariki ndende.', fr: 'Aucun travail à ces dates. Essayez des dates plus larges.', sw: 'Hakuna kazi katika tarehe hizo. Jaribu tarehe pana zaidi.' },
  'report.nothingBetween': { en: 'No days were written down against a monthly plan, and no activities fall in those dates.', rw: 'Nta minsi yanditswe kuri gahunda y’ukwezi, kandi nta bikorwa biri muri izo tariki.', fr: 'Aucune journée n’a été consignée dans un plan mensuel et aucune activité ne tombe sur ces dates.', sw: 'Hakuna siku zilizoandikwa kwa mpango wa mwezi, na hakuna shughuli katika tarehe hizo.' },
  'report.generated': { en: 'generated', rw: 'byakozwe', fr: 'généré', sw: 'imetengenezwa' },
  'report.to': { en: 'to', rw: 'kugeza', fr: 'au', sw: 'hadi' },

  // ---- review screen hints -------------------------------------------------
  'review.sentBackToYou': { en: 'The Director sent this back. Fix what the note asks for, add photos or receipts, and send it for a final check again.', rw: 'Umuyobozi Mukuru yabigaruye. Kosora ibyo icyitonderwa gisaba, wongeremo amafoto cyangwa inyemezabwishyu, hanyuma wongere wohereze isuzuma rya nyuma.', fr: 'Le Directeur l’a renvoyé. Corrigez ce que la note demande, ajoutez photos ou reçus, puis renvoyez-le pour vérification finale.', sw: 'Mkurugenzi ameirudisha. Rekebisha kile maelezo yanachoomba, ongeza picha au risiti, kisha itume tena kwa ukaguzi wa mwisho.' },
  'review.reassignClearsAcceptance': { en: 'The new manager will be asked to accept this work.', rw: 'Umuyobozi mushya azasabwa kwemera aka kazi.', fr: 'Le nouveau responsable devra accepter ce travail.', sw: 'Meneja mpya ataombwa kukubali kazi hii.' },
  'review.needsCorrectionHint': { en: 'This sends the work back to the manager with your note, so they can fix it and send it again.', rw: 'Ibi bigarura akazi ku muyobozi hamwe n’icyitonderwa cyawe, kugira ngo agakosore akongere akohereze.', fr: 'Cela renvoie le travail au responsable avec votre note, pour qu’il le corrige et le renvoie.', sw: 'Hii inarudisha kazi kwa meneja pamoja na maelezo yako, ili airekebishe na kuituma tena.' },
  'review.sentBackBy': { en: 'Sent back by {name} · {date}', rw: 'Byagaruwe na {name} · {date}', fr: 'Renvoyé par {name} · {date}', sw: 'Imerudishwa na {name} · {date}' },
  'review.whatYouChanged': { en: 'What you changed', rw: 'Ibyo wahinduye', fr: 'Ce que vous avez modifié', sw: 'Ulichobadilisha' },
  'review.correctionMoneyLocked': { en: 'The budget stays as it was decided. To change it, ask for a budget change.', rw: 'Ingengo y’imari iguma uko yemejwe. Kugira ngo uyihindure, saba ihinduka ry’ingengo y’imari.', fr: 'Le budget reste tel qu’il a été décidé. Pour le modifier, demandez un changement de budget.', sw: 'Bajeti inabaki kama ilivyoamuliwa. Ili kuibadilisha, omba mabadiliko ya bajeti.' },
  'review.noManagerCoversArea': { en: 'No manager covers this project yet. Add one under “People” before handing this work over.', rw: 'Nta muyobozi urahabwa uyu mushinga. Banza wongereho umwe muri “Abakozi” mbere yo guha undi aka kazi.', fr: 'Aucun responsable ne couvre encore ce projet. Ajoutez-en un dans « Personnes » avant de confier ce travail.', sw: 'Hakuna meneja anayeshughulikia mradi huu bado. Ongeza mmoja katika “Watu” kabla ya kukabidhi kazi hii.' },
