  'apiError.EMPTY_REPORT': { en: 'Write what was done, what it cost, or a note. An empty report saves nothing.', rw: 'Andika ibyakozwe, ibyo byatwaye, cyangwa icyitonderwa. Raporo irimo ubusa ntibika ikintu.', fr: 'Écrivez ce qui a été fait, son coût ou une note. Un rapport vide n’enregistre rien.', sw: 'Andika kilichofanyika, gharama yake, au maelezo. Ripoti tupu haihifadhi chochote.' },
