  'notice.kind.report_submitted': { en: '{name} submitted the {operation} month-end report for {month}. It is waiting for your review.', rw: '{name} yohereje raporo y’impera z’ukwezi ya {operation} ya {month}. Itegereje isuzuma ryawe.', fr: '{name} a soumis le rapport de fin de mois {operation} de {month}. Il attend votre examen.', sw: '{name} amewasilisha ripoti ya mwisho wa mwezi ya {operation} ya {month}. Inasubiri mapitio yako.' },
  'notice.kind.report_accepted': { en: 'Approved: your {operation} report for {month} was accepted and the month is closed.', rw: 'Byemejwe: raporo yawe ya {operation} ya {month} yemewe kandi ukwezi kwafunzwe.', fr: 'Approuvé : votre rapport {operation} de {month} a été accepté et le mois est clôturé.', sw: 'Imeidhinishwa: ripoti yako ya {operation} ya {month} imekubaliwa na mwezi umefungwa.' },
