  'notice.kind.work_submitted': { en: '{name} submitted “{activity}” ({operation}) for your final check.', rw: '{name} yohereje “{activity}” ({operation}) ngo ugenzure bwa nyuma.', fr: '{name} a soumis « {activity} » ({operation}) pour votre vérification finale.', sw: '{name} amewasilisha “{activity}” ({operation}) kwa ukaguzi wako wa mwisho.' },
  'notice.kind.work_approved': { en: 'Approved: “{activity}” was checked and marked done.', rw: 'Byemejwe: “{activity}” yagenzuwe kandi ishyirwa nk’iyarangiye.', fr: 'Approuvé : « {activity} » a été vérifié et marqué comme terminé.', sw: 'Imeidhinishwa: “{activity}” imekaguliwa na kuwekwa kama imekamilika.' },
  'notice.kind.work_returned': { en: 'Needs correction: “{activity}” was sent back. Reason: {reason}', rw: 'Bikeneye gukosorwa: “{activity}” yagarujwe. Impamvu: {reason}', fr: 'À corriger : « {activity} » a été renvoyé. Motif : {reason}', sw: 'Inahitaji marekebisho: “{activity}” imerudishwa. Sababu: {reason}' },
