  'notice.kind.budget_change_requested': { en: '{name} asks for a different budget for “{activity}”: {detail}. {reason}', rw: '{name} asaba ingengo y’imari itandukanye kuri “{activity}”: {detail}. {reason}', fr: '{name} demande un autre budget pour « {activity} » : {detail}. {reason}', sw: '{name} anaomba bajeti tofauti kwa “{activity}”: {detail}. {reason}' },
  'notice.kind.approval_decided': { en: 'Your request “{activity}” was {outcome} by {name}. {reason}', rw: 'Ubusabe bwawe “{activity}” {outcome} na {name}. {reason}', fr: 'Votre demande « {activity} » a été {outcome} par {name}. {reason}', sw: 'Ombi lako “{activity}” {outcome} na {name}. {reason}' },
