  'notice.kind.work_assigned': { en: '{name} gave you work: “{activity}”.', rw: '{name} yaguhaye akazi: “{activity}”.', fr: '{name} vous a confié un travail : « {activity} ».', sw: '{name} amekupa kazi: “{activity}”.' },
