  'export.nothingAtAll': { en: 'Nothing was recorded in these dates: no days against a monthly plan, and no activities.', rw: 'Nta kintu cyanditswe muri izi tariki: nta minsi kuri gahunda y’ukwezi, nta n’ibikorwa.', fr: 'Rien n’a été enregistré sur ces dates : aucune journée sur un plan mensuel, et aucune activité.', sw: 'Hakuna kilichorekodiwa katika tarehe hizi: hakuna siku kwa mpango wa mwezi, na hakuna shughuli.' },
  // The honest answer when a report was asked for one project and the month it
  // covers is not filed under any: the operation HAS a month, it is simply not
  // this project's. Saying "no plan covers these dates" there would read as
  // "nothing was agreed", which is a different and wrong statement.
  'export.monthsNotInProject': { en: 'Months in these dates filed under another project: {count}. Their commitments are not counted here.', rw: 'Amezi muri izi tariki ari ku wundi mushinga: {count}. Ibyemeranyijwe byayo ntibibarirwa hano.', fr: 'Mois de ces dates rattachés à un autre projet : {count}. Leurs engagements ne sont pas comptés ici.', sw: 'Miezi ya tarehe hizi iliyo chini ya mradi mwingine: {count}. Makubaliano yake hayahesabiwi hapa.' },

