  // ---- a team member's finished work, checked by their project manager first ----
  'notice.kind.work_to_check': { en: '{name} finished “{activity}” ({operation}). It is waiting for your check before it goes to the Director.', rw: '{name} yarangije “{activity}” ({operation}). Bitegereje ko ubigenzura mbere yo kujya ku Muyobozi.', fr: '{name} a terminé « {activity} » ({operation}). Le travail attend votre vérification avant d’aller au Directeur.', sw: '{name} amemaliza “{activity}” ({operation}). Inasubiri ukaguzi wako kabla ya kwenda kwa Mkurugenzi.' },
  'do.checkWork': { en: 'Check the work', rw: 'Genzura umurimo', fr: 'Vérifier le travail', sw: 'Kagua kazi' },
  'journey.withManager': { en: 'With the project manager', rw: 'Biri ku muyobozi w’umushinga', fr: 'Chez le chef de projet', sw: 'Iko kwa meneja wa mradi' },
  'next.managerCheckTitle': { en: 'Check this work', rw: 'Genzura uyu murimo', fr: 'Vérifiez ce travail', sw: 'Kagua kazi hii' },
  'next.managerCheckText': { en: 'A team member finished it. Look at the proof: pass it on to the Director for the final check, or send it back with what to fix.', rw: 'Umukozi yawurangije. Reba ibimenyetso: wohereze ku Muyobozi ngo agenzure bwa nyuma, cyangwa uwugarure uvuga icyo gukosora.', fr: 'Un membre de l’équipe l’a terminé. Regardez les preuves : transmettez-le au Directeur pour la vérification finale, ou renvoyez-le avec ce qu’il faut corriger.', sw: 'Mwanachama wa timu ameimaliza. Angalia ushahidi: ipeleke kwa Mkurugenzi kwa ukaguzi wa mwisho, au irudishe ukisema cha kurekebisha.' },
  'next.withManagerTitle': { en: 'With {name} for a check', rw: 'Biri kuri {name} ngo abigenzure', fr: 'Chez {name} pour vérification', sw: 'Iko kwa {name} kwa ukaguzi' },
  'next.withManagerText': { en: 'The project manager checks it first, then it goes to the Director for the final check.', rw: 'Umuyobozi w’umushinga abanza kubigenzura, hanyuma bikajya ku Muyobozi ngo agenzure bwa nyuma.', fr: 'Le chef de projet le vérifie d’abord, puis il va au Directeur pour la vérification finale.', sw: 'Meneja wa mradi anaikagua kwanza, kisha inaenda kwa Mkurugenzi kwa ukaguzi wa mwisho.' },
  'next.withManagerDirector': { en: 'The project manager has not checked it yet. You can still give the final check now.', rw: 'Umuyobozi w’umushinga ntarabigenzura. Ushobora kugenzura bwa nyuma ubu.', fr: 'Le chef de projet ne l’a pas encore vérifié. Vous pouvez quand même faire la vérification finale maintenant.', sw: 'Meneja wa mradi bado hajaikagua. Bado unaweza kufanya ukaguzi wa mwisho sasa.' },
  'action.passToDirector': { en: 'Pass to the Director', rw: 'Ohereza ku Muyobozi', fr: 'Transmettre au Directeur', sw: 'Peleka kwa Mkurugenzi' },
