  'msg.passedToDirector': { en: 'Passed to the Director for the final check.', rw: 'Byoherejwe ku Muyobozi ngo agenzure bwa nyuma.', fr: 'Transmis au Directeur pour la vérification finale.', sw: 'Imepelekwa kwa Mkurugenzi kwa ukaguzi wa mwisho.' },
