  'btq.count.fixFirst': { en: 'Some numbers need checking. Look at the boxes marked in red.', rw: 'Hari imibare ikeneye kurebwa. Reba udusanduku turiho umutuku.', fr: 'Certains chiffres sont à vérifier. Regardez les cases en rouge.', sw: 'Baadhi ya namba zinahitaji kuangaliwa. Tazama visanduku vyekundu.' },
