  'farm.err.NOT_ALLOWED': { en: 'Only the Farming Manager or the Director can do this.', rw: 'Umuyobozi w’ubworozi cyangwa Umuyobozi Mukuru ni bo bonyine babikora.', fr: 'Seuls le responsable de la ferme ou le Directeur peuvent le faire.', sw: 'Meneja wa shamba au Mkurugenzi pekee wanaweza kufanya hivi.' },
  'farm.err.NOT_FOUND': { en: 'That record was not found. Reload the page.', rw: 'Icyo cyanditswe nticyabonetse. Ongera ufungure urupapuro.', fr: 'Enregistrement introuvable. Rechargez la page.', sw: 'Rekodi hiyo haikupatikana. Pakia ukurasa upya.' },
  'farm.err.STOCK_BELOW_ZERO': { en: 'That would leave less than nothing on one of the days. Check the dates and figures, or record what was produced first.', rw: 'Ibyo byatuma umunsi umwe usigarana munsi ya zeru. Reba amatariki n’imibare, cyangwa ubanze wandike ibyatanzwe.', fr: 'Cela laisserait moins que rien un des jours. Vérifiez dates et chiffres, ou enregistrez d’abord la production.', sw: 'Hilo lingeacha chini ya sifuri siku moja. Angalia tarehe na namba, au rekodi uzalishaji kwanza.' },
