  'farm.err.HAS_RECORDS_DEACTIVATE_INSTEAD': { en: 'This animal has records. Switch it off instead; its history stays.', rw: 'Iri tungo rifite ibyanditswe. Rihagarike aho; amateka yaryo agumaho.', fr: 'Cet animal a des enregistrements. Désactivez-le plutôt ; son historique reste.', sw: 'Mnyama huyu ana rekodi. Mzime badala yake; historia yake inabaki.' },
  'farm.err.BUDGET_INVALID': { en: 'The budget must be a number, zero or more.', rw: 'Ingengo y’imari igomba kuba umubare, zeru cyangwa hejuru.', fr: 'Le budget doit être un nombre, zéro ou plus.', sw: 'Bajeti lazima iwe namba, sifuri au zaidi.' },
