  'apiMessage.only_the_director_can_change_the_budget': { en: 'Only the Director can change the budget on an activity.', rw: 'Umuyobozi wenyine ni we uhindura ingengo y’imari y’igikorwa.', fr: 'Seul le Directeur peut changer le budget d’une activité.', sw: 'Mkurugenzi peke yake ndiye anaweza kubadilisha bajeti ya shughuli.' },
