  'apiMessage.this_activity_is_waiting_for_a_decision_2': { en: 'This activity is waiting for a decision. Set the budget when you approve it.', rw: 'Iki gikorwa gitegereje icyemezo. Shyiraho ingengo y’imari igihe ucyemeza.', fr: 'Cette activité attend une décision. Fixez le budget en l’approuvant.', sw: 'Shughuli hii inasubiri uamuzi. Weka bajeti unapoiidhinisha.' },
