  'apiMessage.this_budget_change_was_decided_a_moment': { en: 'This budget change was decided a moment ago. Refresh to see the outcome.', rw: 'Iri hinduka ry’ingengo y’imari ryafashweho icyemezo mu kanya. Vugurura urebe ibyavuyemo.', fr: 'Ce changement de budget vient d’être décidé. Actualisez pour voir le résultat.', sw: 'Mabadiliko haya ya bajeti yameamuliwa sasa hivi. Onyesha upya uone matokeo.' },
  'apiMessage.this_month_has_been_closed_ask_the': { en: 'This month has been closed. Ask the Director to reopen it.', rw: 'Uku kwezi kwarafunzwe. Saba Umuyobozi kongera kugufungura.', fr: 'Ce mois est clôturé. Demandez au Directeur de le rouvrir.', sw: 'Mwezi huu umefungwa. Muombe Mkurugenzi aufungue tena.' },
