  'apiMessage.write_how_many_are_left_of_at': { en: 'Write how many are left of at least one product, then save.', rw: 'Andika umubare usigaye kuri nibura igicuruzwa kimwe, hanyuma ubike.', fr: 'Écrivez combien il en reste pour au moins un produit, puis enregistrez.', sw: 'Andika kiasi kilichobaki kwa angalau bidhaa moja, kisha uhifadhi.' },
  'apiMessage.you_already_have_an_open_till_close': { en: 'You already have an open till. Close it before opening another.', rw: 'Usanzwe ufite kasi ifunguye. Yifunge mbere yo gufungura indi.', fr: 'Vous avez déjà une caisse ouverte. Fermez-la avant d’en ouvrir une autre.', sw: 'Tayari una kasha lililo wazi. Lifunge kabla ya kufungua lingine.' },
  'apiPattern.a_product_called_is_already_in_the': { en: 'A product called "{0}" is already in the shop. To add more of it, use Update stock on that product, or give this one a different name.', rw: 'Igicuruzwa cyitwa “{0}” gisanzwe mu iduka. Koresha “Hindura ibiri mu bubiko” kuri cyo, cyangwa uhitemo irindi zina.', fr: 'Un produit nommé « {0} » existe déjà dans la boutique. Utilisez Mettre à jour le stock, ou choisissez un autre nom.', sw: 'Bidhaa inayoitwa “{0}” tayari iko dukani. Tumia Sasisha akiba juu yake, au chagua jina lingine.' },
  'apiPattern.is_archived_and_cannot_be_counted': { en: '"{0}" is archived and cannot be counted.', rw: '“{0}” cyakuwe ku isoko, ntigishobora kubarwa.', fr: '« {0} » est archivé et ne peut pas être compté.', sw: '“{0}” imeondolewa, haiwezi kuhesabiwa.' },
  'apiPattern.is_no_longer_on_sale': { en: '{0} ({1}) is no longer on sale.', rw: '{0} ({1}) ntikigurishwa.', fr: '{0} ({1}) n’est plus en vente.', sw: '{0} ({1}) haiuzwi tena.' },
