  'apiMessage.choose_one_of_the_four_projects': { en: 'Choose one of the four projects.', rw: 'Hitamo umwe mu mishinga ine.', fr: 'Choisissez un des quatre projets.', sw: 'Chagua mmoja wa miradi minne.' },
