  'apiMessage.describe_the_work_the_person_doing_it': { en: 'Describe the work. The person doing it reads this and nothing else.', rw: 'Sobanura akazi. Ugakora asoma ibi gusa.', fr: 'Décrivez le travail. La personne qui le fait ne lit que cela.', sw: 'Eleza kazi. Anayeifanya anasoma hii tu.' },
