  'apiMessage.the_cost_must_be_a_number_that': { en: 'The cost must be a number that is not negative.', rw: 'Ikiguzi kigomba kuba umubare, zeru cyangwa urenga.', fr: 'Le coût doit être un nombre, zéro ou plus.', sw: 'Gharama lazima iwe namba, sifuri au zaidi.' },
  'apiMessage.the_day_of_the_work_must_be': { en: 'The day of the work must be a real date.', rw: 'Umunsi w’akazi ugomba kuba itariki nyayo.', fr: 'Le jour du travail doit être une vraie date.', sw: 'Siku ya kazi lazima iwe tarehe halisi.' },
  'apiMessage.the_decision_must_be_accepted_or_returned': { en: 'The decision must be Accepted or Returned.', rw: 'Icyemezo kigomba kuba Byemewe cyangwa Bisubijwe.', fr: 'La décision doit être Accepté ou Renvoyé.', sw: 'Uamuzi lazima uwe Imekubaliwa au Imerudishwa.' },
  'apiMessage.the_director_changes_the_plan_directly_rather': { en: 'The Director changes the plan directly rather than asking for a change.', rw: 'Umuyobozi ahindura gahunda ubwe aho gusaba ko ihinduka.', fr: 'Le Directeur modifie le plan directement au lieu de demander un changement.', sw: 'Mkurugenzi hubadilisha mpango moja kwa moja badala ya kuomba mabadiliko.' },
