  'apiMessage.the_director_has_not_confirmed_this_month_2': { en: 'The Director has not confirmed this month yet, so there is nothing to report against.', rw: 'Uku kwezi ntikuraba kwiteguye. Baza Umuyobozi.', fr: 'Ce mois n’est pas encore prêt. Demandez au Directeur.', sw: 'Mwezi huu bado haujawa tayari. Muulize Mkurugenzi.' },
