  'apiMessage.the_month_must_be_in_yyyy_mm': { en: 'The month must be in YYYY-MM form.', rw: 'Ukwezi kugomba kwandikwa nka YYYY-MM.', fr: 'Le mois doit être au format AAAA-MM.', sw: 'Mwezi lazima uandikwe kama YYYY-MM.' },
  'apiMessage.the_work_done_must_be_a_number': { en: 'The work done must be a number that is not negative.', rw: 'Ingano y’akazi igomba kuba umubare, zeru cyangwa urenga.', fr: 'La quantité de travail doit être un nombre, zéro ou plus.', sw: 'Kiasi cha kazi lazima kiwe namba, sifuri au zaidi.' },
  'apiMessage.this_month_has_already_been_closed': { en: 'This month has already been closed.', rw: 'Uku kwezi kwamaze gufungwa.', fr: 'Ce mois est déjà clôturé.', sw: 'Mwezi huu tayari umefungwa.' },
  'apiMessage.this_month_has_already_been_started': { en: 'This month has already been started.', rw: 'Uku kwezi kwamaze gutangira.', fr: 'Ce mois a déjà commencé.', sw: 'Mwezi huu tayari umeanza.' },
  'apiMessage.this_month_has_been_closed': { en: 'This month has been closed.', rw: 'Uku kwezi kwarafunzwe.', fr: 'Ce mois est clôturé.', sw: 'Mwezi huu umefungwa.' },
  'apiMessage.this_month_has_been_closed_ask_for': { en: 'This month has been closed. Ask for it to be reopened first.', rw: 'Uku kwezi kwarafunzwe. Banza usabe ko kongera gufungurwa.', fr: 'Ce mois est clôturé. Demandez d’abord qu’il soit rouvert.', sw: 'Mwezi huu umefungwa. Omba kwanza ufunguliwe tena.' },
  'apiMessage.this_month_has_been_closed_ask_the_2': { en: 'This month has been closed. Ask the Director to reopen it first.', rw: 'Uku kwezi kwarafunzwe. Banza usabe Umuyobozi kongera kugufungura.', fr: 'Ce mois est clôturé. Demandez d’abord au Directeur de le rouvrir.', sw: 'Mwezi huu umefungwa. Muombe Mkurugenzi kwanza aufungue tena.' },
