  'apiMessage.actual_expense_must_be_a_non_negative': { en: 'Actual expense must be a non-negative number.', rw: 'Amafaranga yakoreshejwe koko agomba kuba umubare, zeru cyangwa urenga.', fr: 'La dépense réelle doit être un nombre, zéro ou plus.', sw: 'Matumizi halisi lazima yawe namba, sifuri au zaidi.' },
  'apiMessage.datefrom_must_be_a_valid_date': { en: 'dateFrom must be a valid date.', rw: 'Itariki yo gutangiriraho igomba kuba itariki nyayo.', fr: 'La date de début doit être une date valide.', sw: 'Tarehe ya kuanzia lazima iwe tarehe halali.' },
