// A missing language falls back to English, and an unknown key to itself, so a
// gap shows readable English rather than an empty element or "undefined".
export function translate(language, key) {
  const entry = STRINGS[key];
  if (!entry) return key;
  return entry[language] || entry.en || key;
}

// Puts values into a translated sentence: fill('{name} approved.', { name })
// -> 'Amina approved.'. Word order differs between the four languages, so the
// placeholders are named and each translation places them where it needs to.
export function fill(text, values = {}) {
  return String(text).replace(/\{(\w+)\}/g, (match, name) => (
    Object.prototype.hasOwnProperty.call(values, name) && values[name] !== null && values[name] !== undefined
      ? String(values[name])
      : match
  ));
}

// Every key that is not translated into every language. Used by the test suite
// so a string added in English alone fails a check rather than quietly showing
// English to a Kinyarwanda reader.
export function missingTranslations() {
  const gaps = [];
  for (const [key, entry] of Object.entries(STRINGS)) {
    const missing = LANGUAGE_CODES.filter((code) => !entry[code]);
    if (missing.length) gaps.push({ key, missing });
  }
  return gaps;
}

// [key, English] for every key under a prefix -- how a sentence the server
// sent in English is found again, to be shown in the reader's language.
export function englishEntries(prefix) {
  return Object.entries(STRINGS).filter(([key]) => key.startsWith(prefix)).map(([key, entry]) => [key, entry.en]);
}

export function translationKeys() {
  return Object.keys(STRINGS);
}
